#nullable enable // autogenerated    

using MVZ2.Vanilla.Properties;
using MVZ2Logic;
using MVZ2Logic.Callbacks;
using MVZ2Logic.Contents.Enemies;
using MVZ2Logic.Entities;
using MVZ2Logic.Level;
using MVZ2Logic.Options;
using PVZEngine;
using PVZEngine.Callbacks;
using PVZEngine.Definitions;
using PVZEngine.Entities;
using PVZEngine.Level;
using PVZEngine.Modifiers;
using UnityEngine;

namespace MVZ2.GameContent.Effects  
{  
    [AutoEntityBehaviourDefinition(VanillaEffectNames.minecartRideable)]  
    public class MinecartRideable : EntityBehaviourDefinition  
    {  
        public MinecartRideable(string nsp, string name) : base(nsp, name)  
        {  
            AddTrigger(LogicLevelCallbacks.POST_PAUSE, PostPauseCallback);  
            // 隐形支持：默认可见（tint 白、影子 alpha 1），仅对需要隐形的矿车调用 SetInvisible    
            AddModifier(ColorModifier.Multiply(EngineEntityProps.TINT, PROP_TINT_MULT));  
            AddModifier(new FloatModifier(LogicEntityProps.SHADOW_ALPHA, NumberOperator.Multiply, PROP_SHADOW_ALPHA));  
        }  
        public override void Init(Entity entity)  
        {  
            base.Init(entity);  
            SetTargetPosition(entity, entity.Position);  
            // 初始化“无器械宽限帧”：刚生成时给足宽限，避免器械还没骑上来就被自毁    
            SetNoRiderGrace(entity, NO_RIDER_GRACE);  
        }  
        public override void Update(Entity entity)  
        {  
            base.Update(entity);  
  
            // ===== 无器械自毁逻辑 =====    
            // 需求：矿车没有存活的骑乘器械时应自动销毁，避免场上残留空矿车    
            // 做法：用一个宽限计数器，有存活骑乘器械时重置为满值；    
            //      没有时每帧递减，减到 0 以下则移除自己（return 不再执行后续移动逻辑）    
            var passenger = entity.GetRideablePassenger();  
            if (passenger.ExistsAndAlive())  
            {  
                // 有活着的器械：重置宽限    
                SetNoRiderGrace(entity, NO_RIDER_GRACE);  
            }  
            else  
            {  
                // 没有器械：递减宽限，超时则自毁    
                var grace = GetNoRiderGrace(entity) - 1;  
                SetNoRiderGrace(entity, grace);  
                if (grace <= 0)  
                {  
                    entity.Remove();  
                    return;  
                }  
            }

            var parent = entity.Parent;
            bool hasRail = parent.ExistsAndAlive();
            if (entity.Level.IsGameRunning())
            {
                var controlMode = Global.Options.GetMinecartControlMode();
                if (controlMode == MinecartControlModes.MOUSE)
                {
                    // 鼠标跟随模式：读取指针位置作为目标点（恢复旧机制）  
                    if (Global.Input.TryGetPointerScreenPosition(out var screenPosition))
                    {
                        var target = entity.Level.ScreenToLawnPositionByRelativeY(screenPosition, 0);
                        target = hasRail ? ClampToRail(entity, parent, target) : ClampToLawn(entity, target);
                        SetTargetPosition(entity, target);
                    }
                }
                else
                {
                    // 键盘/按钮模式  
                    var moveInput = GetMoveInput(entity.Level);    // z 轴：上下  
                    var moveInputX = GetMoveInputX(entity.Level);  // x 轴：左右  
                    if (moveInput != 0 || moveInputX != 0)
                    {
                        var baseSpeed = hasRail ? RAIL_MOVE_SPEED : FREE_MOVE_SPEED;
                        var speed = baseSpeed * (1f + GetSpeedLevel(entity.Level) * SPEED_PER_LEVEL);
                        var target = GetTargetPosition(entity);
                        target.z += moveInput * speed;
                        target.x += moveInputX * speed;
                        target = hasRail ? ClampToRail(entity, parent, target) : ClampToLawn(entity, target);
                        SetTargetPosition(entity, target);
                    }
                }
            }
            // 无论有无轨道都追随目标点（clamp 已在上面完成）  
            FollowPointer(entity, hasRail ? parent : null, GetTargetPosition(entity));
        }  
        private Vector3 ClampToRail(Entity entity, Entity parent, Vector3 targetPosition)  
        {  
            var parentBounds = parent.GetBounds();  
            var entityBounds = entity.GetBounds();  
            var minX = parentBounds.min.x + entityBounds.extents.x;  
            var maxX = parentBounds.max.x - entityBounds.extents.x;  
            var minZ = parentBounds.min.z + entityBounds.extents.z;  
            var maxZ = parentBounds.max.z - entityBounds.extents.z;  
            targetPosition.x = minX < maxX ? Mathf.Clamp(targetPosition.x, minX, maxX) : parent.Position.x;  
            targetPosition.z = minZ < maxZ ? Mathf.Clamp(targetPosition.z, minZ, maxZ) : parent.Position.z;  
            return targetPosition;  
        }  
        // 无轨道时限制在地图可视范围内，避免跑出摄像机    
        private Vector3 ClampToLawn(Entity entity, Vector3 targetPosition)  
        {  
            var level = entity.Level;  
            targetPosition.x = Mathf.Clamp(targetPosition.x, LevelPositions.GetBorderX(false), LevelPositions.GetBorderX(true));  
            // 按场地格子的上下范围限制 z    
            targetPosition.z = Mathf.Clamp(targetPosition.z, level.GetGridBottomZ(), level.GetGridTopZ());  
            return targetPosition;  
        }  
        private void FollowPointer(Entity entity, Entity? parent, Vector3 targetPosition)  
        {  
            // 注意：这里不再做 clamp，clamp 已在 Update 中完成；    
            // 本方法只负责带阻尼地平滑追随 targetPosition    
            var distance = targetPosition - entity.Position;  
            var magnitude = Mathf.Max(0, distance.magnitude - 24f);  
            distance = magnitude * distance.normalized;  
            entity.Velocity = distance * VELOCITY_DAMP;  
        }  
        private void PostPauseCallback(LevelCallbackParams param, CallbackResult result)  
        {  
            var level = param.level;  
            foreach (var cart in level.FindEntities(e => e.HasBehaviour(this)))  
            {  
                cart.Velocity = Vector3.zero;  
                SetTargetPosition(cart, cart.Position);  
            }  
        }  
        // 让指定矿车隐形（tint/影子 alpha 归零），只影响调用它的这辆    
        public static void SetInvisible(Entity entity)  
        {  
            entity.SetBehaviourField(PROP_TINT_MULT, new Color(1, 1, 1, 0));  
            entity.SetBehaviourField(PROP_SHADOW_ALPHA, 0f);  
        }  
  
        // ===== 单例矿车保证 =====    
        // 需求：任意时刻场上最多只存在一辆矿车。    
        // 各关卡的 SpawnOrFindMinecart/SpawnOrFindCart 应改为先调用本方法：    
        //   - 若已有存活矿车，返回“第一辆”并把其余多出来的矿车全部移除（清理历史残留的重复矿车）；    
        //   - 若没有存活矿车，返回 null，由调用方自行 Spawn 新矿车。    
        // 这样即使某一帧出现了复数矿车，也会被收敛回单辆，FindRider/FindCart 不再命中空的残留矿车。    
        public static Entity? FindSingleCart(LevelEngine level)  
        {  
            Entity? kept = null;  
            foreach (var cart in level.FindEntities(VanillaEffectID.minecartRideable))  
            {  
                if (!cart.ExistsAndAlive())  
                    continue;  
                if (kept == null)  
                {  
                    // 保留找到的第一辆存活矿车    
                    kept = cart;  
                }  
                else  
                {  
                    // 多余的重复矿车一律移除，保证场上只剩一辆    
                    cart.Remove();  
                }  
            }  
            return kept;  
        }  
  
        public static Vector3 GetTargetPosition(Entity entity) => entity.GetBehaviourField<Vector3>(PROP_TARGET_POSITION);  
        public static void SetTargetPosition(Entity entity, Vector3 value) => entity.SetBehaviourField(PROP_TARGET_POSITION, value);  
  
        // 无器械宽限计数器读写（每辆矿车各自维护）    
        public static int GetNoRiderGrace(Entity entity) => entity.GetBehaviourField<int>(PROP_NO_RIDER_GRACE);  
        public static void SetNoRiderGrace(Entity entity, int value) => entity.SetBehaviourField(PROP_NO_RIDER_GRACE, value);  
  
        public static int GetMoveInput(LevelEngine level) => level.GetProperty<int>(PROP_MOVE_INPUT);  
        public static void SetMoveInput(LevelEngine level, int value) => level.SetProperty(PROP_MOVE_INPUT, value);  
        public static int GetMoveInputX(LevelEngine level) => level.GetProperty<int>(PROP_MOVE_INPUT_X);  
        public static void SetMoveInputX(LevelEngine level, int value) => level.SetProperty(PROP_MOVE_INPUT_X, value);

        // 矿车速度升级等级（存在关卡属性上，矿车重生后依然保留）  
        public static int GetSpeedLevel(LevelEngine level) => level.GetProperty<int>(PROP_SPEED_LEVEL);
        public static void SetSpeedLevel(LevelEngine level, int value) => level.SetProperty(PROP_SPEED_LEVEL, value);

        public const float SPEED_PER_LEVEL = 0.3f;  // 每级增量
        public const int MAX_SPEED_LEVEL = 5;       // 满级上限

        [LevelPropertyRegistry(PROP_REGION)]
        public static readonly VanillaLevelPropertyMeta<int> PROP_SPEED_LEVEL =
            new VanillaLevelPropertyMeta<int>("hw_speed_level");

        public const float VELOCITY_DAMP = 0.1f;  
        public const float RAIL_MOVE_SPEED = 12f;   // 轨道上速度（可调）    
        public const float FREE_MOVE_SPEED = 8f;    // 脱离轨道速度（可调）    
        public const int NO_RIDER_GRACE = 5;        // 无器械宽限帧数：连续这么多帧没有存活器械才自毁（可调）    
        public static readonly VanillaEntityPropertyMeta<Vector3> PROP_TARGET_POSITION = new VanillaEntityPropertyMeta<Vector3>("target_position");  
        public static readonly VanillaEntityPropertyMeta<Color> PROP_TINT_MULT = new VanillaEntityPropertyMeta<Color>("tint_mult", Color.white);  
        public static readonly VanillaEntityPropertyMeta<float> PROP_SHADOW_ALPHA = new VanillaEntityPropertyMeta<float>("shadow_alpha", 1f);  
        public static readonly VanillaEntityPropertyMeta<int> PROP_NO_RIDER_GRACE = new VanillaEntityPropertyMeta<int>("no_rider_grace");  
        private const string PROP_REGION = "minecart_rideable";  
        [LevelPropertyRegistry(PROP_REGION)]  
        public static readonly VanillaLevelPropertyMeta<int> PROP_MOVE_INPUT = new VanillaLevelPropertyMeta<int>("move_input");  
        [LevelPropertyRegistry(PROP_REGION)]  
        public static readonly VanillaLevelPropertyMeta<int> PROP_MOVE_INPUT_X = new VanillaLevelPropertyMeta<int>("move_input_x");  
    }  
}
